from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, Field, ValidationError, condecimal, conint, validator


class Line(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: condecimal(ge=0, max_digits=20, decimal_places=2)

    @validator("unit_price", pre=True)
    def parse_unit_price(cls, v):
        # Accept str/int/float, convert to Decimal with 2 decimals exactly
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        # Quantize to 2 decimal places, rounding down to avoid rounding surprises
        d = d.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        return d


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    class Config:
        # No orm_mode needed here
        arbitrary_types_allowed = True

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for the billing API.
    Output JSON includes "number", "issued_at" formatted as YYYY-MM-DDTHH:MM:SSZ in UTC,
    "lines" with "sku", "quantity", "unit_price" as string with 2 decimals,
    and "total" as string with 2 decimals.
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Compute total as Decimal sum of quantity * unit_price
    total = sum((line.quantity * line.unit_price for line in invoice.lines), Decimal("0.00"))
    # Format total as string with exactly two decimals
    total_str = f"{total:.2f}"

    # Format issued_at as YYYY-MM-DDTHH:MM:SSZ
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with unit_price as string with 2 decimals
    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": f"{line.unit_price:.2f}",
        })

    # Compose output dict
    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }

    # Return JSON text
    import json
    return json.dumps(out, separators=(",", ":"))

from pydantic import BaseModel, Field, root_validator, validator, ValidationError
import re


class SignupPayload(BaseModel):
    username: str = Field(..., regex=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @validator("email")
    def email_must_contain_at(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @validator("phone")
    def normalize_phone(cls, v: str) -> str:
        if not isinstance(v, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", v)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @root_validator
    def passwords_match(cls, values):
        pw = values.get("password")
        pwc = values.get("password_confirm")
        if pw is not None and pwc is not None and pw != pwc:
            raise ValueError("passwords do not match")
        return values


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload dict using pydantic.

    Returns a dict with keys: username, email (stripped and lowercased), phone (compact form).
    Raises ValueError (ValidationError) on invalid or missing fields.
    """
    validated = SignupPayload.parse_obj(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import List, Union
from pydantic import BaseModel, Field, ValidationError, model_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @model_validator(mode='before')
    @classmethod
    def parse_unit_price(cls, values):
        # Coerce unit_price from str/int/float to Decimal before validation
        up = values.get('unit_price')
        if up is None:
            return values
        try:
            values['unit_price'] = Decimal(str(up))
        except Exception as e:
            raise ValueError(f"unit_price must be a decimal convertible value: {e}") from e
        return values


class Invoice(BaseModel):
    number: str
    issued_at: Union[datetime, str]
    lines: List[InvoiceLine]

    model_config = {
        'from_attributes': True,
    }

    @model_validator(mode='before')
    @classmethod
    def parse_issued_at(cls, values):
        dt = values.get('issued_at')
        if dt is None:
            return values
        if isinstance(dt, str):
            try:
                # Parse ISO 8601 string
                # datetime.fromisoformat does not parse 'Z', so replace Z with +00:00
                s = dt
                if s.endswith('Z'):
                    s = s[:-1] + '+00:00'
                dt_parsed = datetime.fromisoformat(s)
            except Exception as e:
                raise ValueError(f"issued_at must be a valid ISO 8601 datetime string: {e}") from e
            values['issued_at'] = dt_parsed
        elif not isinstance(dt, datetime):
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        return values

    @model_validator(mode='after')
    def normalize_issued_at(self):
        dt = self.issued_at
        if dt.tzinfo is None:
            # naive datetime, treat as UTC
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            # convert to UTC
            dt = dt.astimezone(timezone.utc)
        object.__setattr__(self, 'issued_at', dt)
        return self

    def total(self) -> Decimal:
        total = Decimal('0')
        for line in self.lines:
            total += line.unit_price * line.quantity
        return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Prepare output dict
    issued_at_str = invoice.issued_at.strftime('%Y-%m-%dT%H:%M:%SZ')

    def format_price(d: Decimal) -> str:
        return f"{d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"

    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            'sku': line.sku,
            'quantity': line.quantity,
            'unit_price': format_price(line.unit_price),
        })

    total_str = format_price(invoice.total())

    import json
    out = {
        'number': invoice.number,
        'issued_at': issued_at_str,
        'lines': lines_out,
        'total': total_str,
    }
    return json.dumps(out, separators=(',', ':'))

from typing import Any, Optional
from pydantic import BaseModel, Field, ValidationError, field_validator


class Profile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    model_config = {
        "from_attributes": True,
    }

    @field_validator("display_name")
    @classmethod
    def collapse_whitespace(cls, v: str) -> str:
        # Collapse internal whitespace to single spaces and strip ends
        collapsed = " ".join(v.split())
        if not collapsed:
            raise ValueError("display_name cannot be blank")
        return collapsed

    @field_validator("zip_code", mode="before")
    @classmethod
    def coerce_zip_code_to_str(cls, v: Any) -> str:
        # Accept int or str, convert to str
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        raise TypeError("zip_code must be str or int")


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except ValidationError:
            continue
        valid_profiles.append(profile.model_dump())
    return valid_profiles

from typing import List
from pydantic import BaseModel


class CustomerModel(BaseModel):
    id: int
    name: str
    email: str

    model_config = {
        'from_attributes': True,
    }


class ItemModel(BaseModel):
    sku: str
    quantity: int

    model_config = {
        'from_attributes': True,
    }


class OrderModel(BaseModel):
    id: int
    customer: CustomerModel
    items: List[ItemModel]

    model_config = {
        'from_attributes': True,
    }


def orders_payload(orders: list) -> list:
    try:
        validated_orders = [OrderModel.model_validate(order) for order in orders]
    except Exception as e:
        # Pydantic ValidationError inherits from ValueError, so this is consistent with the request
        raise ValueError(str(e)) from e
    return [order.model_dump() for order in validated_orders]

import re
from pydantic import BaseModel, Field, ValidationError, field_validator


class SignupModel(BaseModel):
    username: str = Field(pattern=r'^[a-z0-9_]{3,20}$')
    email: str
    phone: str
    password: str = Field(min_length=8)
    password_confirm: str

    model_config = {
        'populate_by_name': True,
        'str_strip_whitespace': True,
        'from_attributes': True,
    }

    @field_validator('email')
    @classmethod
    def validate_email(cls, v: str) -> str:
        v = v.strip().lower()
        if '@' not in v:
            raise ValueError('email must contain "@"')
        return v

    @field_validator('phone')
    @classmethod
    def validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r'[ \.\-\(\)]', '', v)
        if not re.fullmatch(r'\+[0-9]{8,15}', compact):
            raise ValueError('phone must be "+" followed by 8-15 digits after removing spaces, dots, dashes, parentheses')
        return compact

    @field_validator('password_confirm')
    @classmethod
    def validate_password_confirm(cls, v: str, info) -> str:
        # We need to compare with password field value
        values = info.data
        password = values.get('password')
        if password is None:
            # password missing will be caught by other validator
            return v
        if v != password:
            raise ValueError('password_confirm must equal password')
        return v

    def model_dump(self, *args, **kwargs):
        # Override to exclude password fields from output
        return super().model_dump(*args, **kwargs, include={'username', 'email', 'phone'})


def validate_signup(data: dict) -> dict:
    try:
        m = SignupModel.model_validate(data)
    except ValidationError as e:
        # Re-raise as ValueError to comply with request
        raise e
    return m.model_dump()
